1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body { margin: 0; font: 16px/1.4 system-ui, sans-serif; background: #f6f6f4; color: #222; }
10	  main { max-width: 520px; margin: 40px auto; padding: 0 16px; }
11	  h1 { font-size: 1.6rem; margin: 0 0 16px; }
12	  form { display: flex; gap: 8px; margin-bottom: 16px; }
13	  input { flex: 1; padding: 10px; font: inherit; border: 1px solid #ccc; border-radius: 6px; }
14	  button { padding: 10px 14px; font: inherit; border: 0; border-radius: 6px; background: #2b6cb0; color: #fff; cursor: pointer; }
15	  ul { list-style: none; margin: 0; padding: 0; }
16	  li { display: flex; align-items: center; gap: 8px; padding: 10px 12px; background: #fff; border: 1px solid #e3e3e3; border-radius: 6px; margin-bottom: 8px; }
17	  li span { flex: 1; word-break: break-word; }
18	  li button { background: #c53030; padding: 6px 10px; font-size: 0.9rem; }
19	  li input[type="checkbox"] { flex: none; width: 18px; height: 18px; margin: 0; }
20	  li[data-completed="true"] span { text-decoration: line-through; color: #888; }
21	  input[type="date"] { flex: none; }
22	  li .due { flex: none; font-size: 0.85rem; color: #555; }
23	  select { flex: none; padding: 10px; font: inherit; border: 1px solid #ccc; border-radius: 6px; background: #fff; }
24	  li { border-left-width: 6px; }
25	  li[data-priority="high"] { background: #fff5f5; }
26	  li[data-priority="med"] { background: #fffaf0; }
27	  li[data-priority="low"] { background: #f7f7f7; }
28	  li[data-overdue="true"] { border-color: #c53030; background: #fff5f5; }
29	  li[data-priority="high"] { border-left-color: #c53030; }
30	  li[data-priority="med"] { border-left-color: #d69e2e; }
31	  li[data-priority="low"] { border-left-color: #a0aec0; }
32	  li[data-overdue="true"] .due { color: #c53030; font-weight: 600; }
33	  .filters { display: flex; gap: 8px; margin-bottom: 16px; }
34	  .filters button { background: #e2e8f0; color: #222; padding: 6px 12px; font-size: 0.9rem; }
35	  .filters button[aria-pressed="true"] { background: #2b6cb0; color: #fff; }
36	</style>
37	</head>
38	<body>
39	<main>
40	  <h1>Todos</h1>
41	  <form id="todo-form">
42	    <input data-testid="todo-input" type="text" placeholder="What needs doing?" autocomplete="off" aria-label="New todo">
43	    <input data-testid="todo-due" type="date" aria-label="Due date">
44	    <select data-testid="todo-priority" aria-label="Priority">
45	      <option value="low">Low</option>
46	      <option value="med" selected>Med</option>
47	      <option value="high">High</option>
48	    </select>
49	    <button data-testid="todo-add" type="submit">Add</button>
50	  </form>
51	  <div class="filters">
52	    <button data-testid="filter-all" data-filter="all" type="button" aria-pressed="true">All</button>
53	    <button data-testid="filter-active" data-filter="active" type="button" aria-pressed="false">Active</button>
54	    <button data-testid="filter-completed" data-filter="completed" type="button" aria-pressed="false">Completed</button>
55	  </div>
56	  <ul data-testid="todo-list"></ul>
57	</main>
58	<script>
59	  var STORAGE_KEY = 'todos';
60	  var form = document.getElementById('todo-form');
61	  var input = document.querySelector('[data-testid="todo-input"]');
62	  var dueInput = document.querySelector('[data-testid="todo-due"]');
63	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
64	  var list = document.querySelector('[data-testid="todo-list"]');
65	  var filterButtons = document.querySelectorAll('[data-filter]');
66	  var todos = loadTodos();
67	  var currentFilter = 'all';
68	
69	  // [REQ-001]
70	  function loadTodos() {
71	    try {
72	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
73	      return Array.isArray(data) ? data : [];
74	    } catch (e) {
75	      return [];
76	    }
77	  }
78	
79	  // [REQ-001]
80	  function saveTodos() {
81	    try {
82	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
83	    } catch (e) {}
84	  }
85	
86	  // [REQ-001]
87	  function makeId() {
88	    if (window.crypto && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
89	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
90	  }
91	
92	  // [REQ-003] Due dates are plain local YYYY-MM-DD strings; never parsed through UTC.
93	  function normalizeDue(value) {
94	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : null;
95	  }
96	
97	  // [REQ-003] Today's LOCAL calendar date as YYYY-MM-DD.
98	  function localToday(now) {
99	    now = now || new Date();
100	    var m = String(now.getMonth() + 1).padStart(2, '0');
101	    var d = String(now.getDate()).padStart(2, '0');
102	    return now.getFullYear() + '-' + m + '-' + d;
103	  }
104	
105	  // [REQ-003] Overdue = due date strictly before today's local date (date-only string compare).
106	  function isOverdue(due, today) {
107	    return !!due && due < today;
108	  }
109	
110	  // [REQ-004] Priority is low, med or high; anything else (including missing) is med.
111	  function normalizePriority(value) {
112	    return value === 'low' || value === 'high' ? value : 'med';
113	  }
114	
115	  // [REQ-001] [REQ-003] [REQ-004]
116	  function addTodo(text, due, priority) {
117	    text = text.trim();
118	    if (!text) return;
119	    todos.push({ id: makeId(), text: text, createdAt: Date.now(), completed: false, due: normalizeDue(due), priority: normalizePriority(priority) });
120	    saveTodos();
121	    render();
122	  }
123	
124	  // [REQ-001]
125	  function deleteTodo(id) {
126	    todos = todos.filter(function (t) { return t.id !== id; });
127	    saveTodos();
128	    render();
129	  }
130	
131	  // [REQ-002]
132	  function toggleTodo(id) {
133	    todos.forEach(function (t) {
134	      if (t.id === id) t.completed = !t.completed;
135	    });
136	    saveTodos();
137	    render();
138	  }
139	
140	  // [REQ-005] Highest priority first; insertion order within the same priority. Does not mutate items.
141	  function byPriority(items) {
142	    var rank = { high: 0, med: 1, low: 2 };
143	    return items
144	      .map(function (t, i) { return { t: t, i: i }; })
145	      .sort(function (a, b) {
146	        return (rank[normalizePriority(a.t.priority)] - rank[normalizePriority(b.t.priority)]) || (a.i - b.i);
147	      })
148	      .map(function (x) { return x.t; });
149	  }
150	
151	  // [REQ-002] [REQ-005] Active todos first, then completed; by priority, then insertion order within each group.
152	  function visibleTodos(items, filter) {
153	    var active = byPriority(items.filter(function (t) { return !t.completed; }));
154	    var done = byPriority(items.filter(function (t) { return !!t.completed; }));
155	    if (filter === 'active') return active;
156	    if (filter === 'completed') return done;
157	    return active.concat(done);
158	  }
159	
160	  // [REQ-002]
161	  function setFilter(filter) {
162	    currentFilter = filter;
163	    render();
164	  }
165	
166	  // [REQ-001] [REQ-002] [REQ-003] [REQ-004]
167	  function render() {
168	    var today = localToday();
169	    list.textContent = '';
170	    filterButtons.forEach(function (btn) {
171	      btn.setAttribute('aria-pressed', String(btn.dataset.filter === currentFilter));
172	    });
173	    visibleTodos(todos, currentFilter).forEach(function (todo) {
174	      var li = document.createElement('li');
175	      li.setAttribute('data-testid', 'todo-item');
176	      li.setAttribute('data-completed', String(!!todo.completed));
177	      li.setAttribute('data-overdue', String(isOverdue(normalizeDue(todo.due), today)));
178	      li.setAttribute('data-priority', normalizePriority(todo.priority));
179	      li.dataset.id = todo.id;
180	
181	      var toggle = document.createElement('input');
182	      toggle.type = 'checkbox';
183	      toggle.setAttribute('data-testid', 'todo-toggle');
184	      toggle.setAttribute('aria-label', 'Mark complete');
185	      toggle.checked = !!todo.completed;
186	      toggle.addEventListener('change', function () { toggleTodo(todo.id); });
187	
188	      var span = document.createElement('span');
189	      span.setAttribute('data-testid', 'todo-text');
190	      span.textContent = todo.text;
191	
192	      var del = document.createElement('button');
193	      del.type = 'button';
194	      del.setAttribute('data-testid', 'todo-delete');
195	      del.textContent = 'Delete';
196	      del.addEventListener('click', function () { deleteTodo(todo.id); });
197	
198	      li.appendChild(toggle);
199	      li.appendChild(span);
200	      if (normalizeDue(todo.due)) {
201	        var due = document.createElement('span');
202	        due.className = 'due';
203	        due.setAttribute('data-testid', 'todo-due-label');
204	        due.textContent = 'Due ' + todo.due;
205	        li.appendChild(due);
206	      }
207	      li.appendChild(del);
208	      list.appendChild(li);
209	    });
210	  }
211	
212	  filterButtons.forEach(function (btn) {
213	    btn.addEventListener('click', function () { setFilter(btn.dataset.filter); });
214	  });
215	
216	  form.addEventListener('submit', function (e) {
217	    e.preventDefault();
218	    addTodo(input.value, dueInput.value, priorityInput.value);
219	    input.value = '';
220	    dueInput.value = '';
221	    priorityInput.value = 'med';
222	    input.focus();
223	  });
224	
225	  render();
226	</script>
227	</body>
228	</html>
